           <div className="bg-white border-y border-slate-200 mb-3">
              <div className="px-5 py-4 flex justify-between items-center border-b border-slate-100">
                 <span className="text-sm font-bold text-slate-800">群聊名称</span>
                 <div className="flex items-center text-slate-500 text-xs">
                    系统神学 19届
                    <ChevronRight size={16} className="ml-1"/>
                 </div>
              </div>
              <div className="px-5 py-4 flex justify-between items-center border-b border-slate-100">
                 <span className="text-sm font-bold text-slate-800">群公告</span>
                 <div className="flex items-center text-slate-500 text-xs truncate max-w-[200px]">
                    本群为学术交流群，请保持...
                    <ChevronRight size={16} className="ml-1 shrink-0"/>
                 </div>
              </div>
              <div className="px-5 py-4 flex justify-between items-center">
                 <span className="text-sm font-bold text-slate-800">共享文件</span>
                 <div className="flex items-center text-slate-500 text-xs">
                    <FolderOpen size={16} className="mr-2"/>
                    <ChevronRight size={16} />
                 </div>
              </div>
           </div>

           {/* User Permissions */}
           <div className="bg-white border-y border-slate-200 mb-3">
              <div className="px-5 py-4 flex justify-between items-center border-b border-slate-100">
                 <span className="text-sm font-bold text-slate-800">消息免打扰</span>
                 <button onClick={toggleMute} className="transition-colors active:scale-95">
                    {userSettings.isMuted ? (
                        <ToggleRight size={32} className="text-blue-600 fill-blue-100" />
                    ) : (
                        <ToggleLeft size={32} className="text-slate-300" />
                    )}
                 </button>
              </div>
              <div className="px-5 py-4 flex justify-between items-center">
                 <span className="text-sm font-bold text-slate-800">置顶聊天</span>
                 <button onClick={togglePin} className="transition-colors active:scale-95">
                    {userSettings.isPinned ? (
                        <ToggleRight size={32} className="text-blue-600 fill-blue-100" />
                    ) : (
                        <ToggleLeft size={32} className="text-slate-300" />
                    )}
                 </button>
              </div>
           </div>

           {/* Group Management (Admins Only) */}
           {canManage && (
               <div className="bg-white border-y border-slate-200 mb-3">
                  <div className="px-5 py-2 bg-slate-50 border-b border-slate-100">
                      <span className="text-xs font-bold text-slate-500 uppercase tracking-wider">群管理</span>
                  </div>
                  <div className="px-5 py-3 flex justify-between items-center border-b border-slate-100">
                     <span className="text-sm font-bold text-slate-800">仅群主/管理员可邀请</span>
                     <button onClick={() => toggleGroupSetting('onlyAdminInvite')}>
                        {groupSettings.onlyAdminInvite ? <ToggleRight size={32} className="text-blue-600 fill-blue-100"/> : <ToggleLeft size={32} className="text-slate-300"/>}
                     </button>
                  </div>
                  <div className="px-5 py-3 flex justify-between items-center border-b border-slate-100">
                     <span className="text-sm font-bold text-slate-800">仅群主/管理员可编辑群信息</span>
                     <button onClick={() => toggleGroupSetting('onlyAdminEdit')}>
                        {groupSettings.onlyAdminEdit ? <ToggleRight size={32} className="text-blue-600 fill-blue-100"/> : <ToggleLeft size={32} className="text-slate-300"/>}
                     </button>
                  </div>
                  <div className="px-5 py-3 flex justify-between items-center">
                     <span className="text-sm font-bold text-slate-800 text-rose-600">全员禁言</span>
                     <button onClick={() => toggleGroupSetting('muteAll')}>
                        {groupSettings.muteAll ? <ToggleRight size={32} className="text-rose-500 fill-rose-100"/> : <ToggleLeft size={32} className="text-slate-300"/>}
                     </button>
                  </div>
               </div>
           )}

           <div className="bg-white border-y border-slate-200 mb-6">
              <div className="px-5 py-4 flex justify-between items-center">
                 <span className="text-sm font-bold text-slate-800">我在本群的昵称</span>
                 <div className="flex items-center text-slate-500 text-xs" onClick={() => showToast("暂不支持修改昵称")}>
                    张神学生
                    <ChevronRight size={16} className="ml-1"/>
                 </div>
              </div>
           </div>

           <div className="px-4 mb-8">
              <button 
                onClick={handleQuitGroup}
                className="w-full bg-white border border-rose-100 text-rose-500 font-bold py-3.5 rounded-xl shadow-sm hover:bg-rose-50 transition"
              >
                 退出群聊
              </button>
           </div>
        </div>

        {/* Modals within Group Detail */}
        {showAddMemberModal && (
            <div className="fixed inset-0 z-[60] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
                <div className="bg-white w-full max-w-sm rounded-3xl p-6 animate-scale-in relative shadow-2xl flex flex-col max-h-[80vh]">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold text-slate-900">添加成员</h3>
                        <button onClick={() => {setShowAddMemberModal(false); setSelectedCandidates([]);}} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar border border-slate-100 rounded-xl p-2 bg-slate-50">
                        {INITIAL_CONTACTS.filter(c => !groupMembers.some(m => m.id === c.id)).map(contact => (
                            <div 
                                key={contact.id} 
                                onClick={() => setSelectedCandidates(prev => prev.includes(contact.id) ? prev.filter(id => id !== contact.id) : [...prev, contact.id])}
                                className={`flex items-center p-2 rounded-xl mb-1 cursor-pointer transition-all ${selectedCandidates.includes(contact.id) ? 'bg-blue-50 border border-blue-200' : 'hover:bg-white border border-transparent'}`}
                            >
                                <div className={`w-5 h-5 rounded-full border flex items-center justify-center mr-3 ${selectedCandidates.includes(contact.id) ? 'bg-blue-600 border-blue-600' : 'bg-white border-slate-300'}`}>
                                    {selectedCandidates.includes(contact.id) && <Check size={12} className="text-white" strokeWidth={3}/>}
                                </div>
                                <img src={contact.avatar} className="w-8 h-8 rounded-full mr-3 object-cover" />
                                <span className="text-sm font-medium text-slate-700">{contact.name}</span>
                            </div>
                        ))}
                        {INITIAL_CONTACTS.filter(c => !groupMembers.some(m => m.id === c.id)).length === 0 && (
                            <div className="text-center py-4 text-xs text-slate-400">没有更多可添加的联系人</div>
                        )}
                    </div>
                    <button 
                        onClick={handleAddMembers}
                        disabled={selectedCandidates.length === 0}
                        className="w-full bg-blue-900 text-white py-3 rounded-xl font-bold shadow-lg mt-4 hover:bg-blue-800 disabled:opacity-50 transition-all"
                    >
                        添加 ({selectedCandidates.length})
                    </button>
                </div>
            </div>
        )}

        {showRemoveMemberModal && (
            <div className="fixed inset-0 z-[60] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
                <div className="bg-white w-full max-w-sm rounded-3xl p-6 animate-scale-in relative shadow-2xl flex flex-col max-h-[80vh]">
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold text-slate-900">移除成员</h3>
                        <button onClick={() => {setShowRemoveMemberModal(false); setSelectedCandidates([]);}} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
                    </div>
                    <div className="flex-1 overflow-y-auto custom-scrollbar border border-slate-100 rounded-xl p-2 bg-slate-50">
                        {groupMembers.filter(m => m.id !== 'me' && (isOwner || (isAdmin && m.role === 'member'))).map(member => (
                            <div 
                                key={member.id} 
                                onClick={() => setSelectedCandidates(prev => prev.includes(member.id) ? prev.filter(id => id !== member.id) : [...prev, member.id])}
                                className={`flex items-center p-2 rounded-xl mb-1 cursor-pointer transition-all ${selectedCandidates.includes(member.id) ? 'bg-rose-50 border border-rose-200' : 'hover:bg-white border border-transparent'}`}
                            >
                                <div className={`w-5 h-5 rounded-full border flex items-center justify-center mr-3 ${selectedCandidates.includes(member.id) ? 'bg-rose-500 border-rose-500' : 'bg-white border-slate-300'}`}>
                                    {selectedCandidates.includes(member.id) && <X size={12} className="text-white" strokeWidth={3}/>}
                                </div>
                                <img src={member.avatar} className="w-8 h-8 rounded-full mr-3 object-cover" />
                                <span className="text-sm font-medium text-slate-700">{member.name}</span>
                                {member.role === 'admin' && <span className="ml-auto text-[9px] bg-blue-100 text-blue-600 px-1.5 py-0.5 rounded">管理员</span>}
                            </div>
                        ))}
                    </div>
                    <button 
                        onClick={handleRemoveMemberConfirm}
                        disabled={selectedCandidates.length === 0}
                        className="w-full bg-rose-600 text-white py-3 rounded-xl font-bold shadow-lg mt-4 hover:bg-rose-700 disabled:opacity-50 transition-all"
                    >
                        移除 ({selectedCandidates.length})
                    </button>
                </div>
            </div>
        )}

        <MemberProfileModal />
        <UserHomepageModal />
      </div>
    );
  }

  // --- Main Chat View ---
  return (
    <div className="flex flex-col h-screen bg-slate-100 animate-slide-in-right relative">
      {/* Toast Notification */}
      {toastMsg && (
         <div className="fixed top-20 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-4 py-2 rounded-full text-xs font-bold shadow-lg z-[100] animate-fade-in flex items-center">
            <CheckCircle size={14} className="mr-2 text-emerald-400"/>
            {toastMsg}
         </div>
      )}

      {/* Confirmation Modal */}
      {confirmDialog && (
          <div className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in">
              <div className="bg-white w-full max-w-xs rounded-2xl p-5 shadow-2xl animate-scale-in text-center">
                  <div className="w-12 h-12 bg-amber-100 text-amber-500 rounded-full flex items-center justify-center mx-auto mb-3">
                      <AlertTriangle size={24} />
                  </div>
                  <h3 className="text-base font-bold text-slate-900 mb-2">确认操作</h3>
                  <p className="text-sm text-slate-500 mb-5 leading-relaxed">{confirmDialog.msg}</p>
                  <div className="flex space-x-3">
                      <button onClick={() => setConfirmDialog(null)} className="flex-1 py-2.5 bg-slate-100 text-slate-600 rounded-xl font-bold text-sm hover:bg-slate-200">取消</button>
                      <button onClick={confirmDialog.action} className="flex-1 py-2.5 bg-blue-900 text-white rounded-xl font-bold text-sm hover:bg-blue-800">确定</button>
                  </div>
              </div>
          </div>
      )}

      {/* Header */}
      <div className="bg-white px-4 py-3 pt-safe-top border-b border-slate-200 flex items-center justify-between sticky top-0 z-30 shadow-sm">
         <div className="flex items-center">
            <button onClick={onBack} className="p-2 -ml-2 hover:bg-slate-100 rounded-full transition">
               <ChevronLeft size={24} className="text-slate-600"/>
            </button>
            <div className="ml-1">
               <h2 className="text-base font-bold text-slate-900 flex items-center">
                  系统神学 19届 
                  <span className="ml-2 text-xs font-normal text-slate-500 bg-slate-100 px-1.5 py-0.5 rounded-full">Group</span>
               </h2>
            </div>
         </div>
         <div className="flex items-center space-x-2">
            <button onClick={() => onJoinRoom?.({ id: 'custom-room', type: 'fellowship', label: '小组语音', icon: Coffee, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: '点击加入语音会议', action: 'voice', participants: 0 })} className="p-2 hover:bg-slate-100 rounded-full transition text-slate-600">
               <Radio size={20} />
            </button>
            <button onClick={() => setShowGroupDetail(true)} className="p-2 -mr-2 hover:bg-slate-100 rounded-full transition text-slate-600">
               <MoreVertical size={20} />
            </button>
         </div>
      </div>

      {/* Messages Area */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-slate-100" style={{backgroundImage: 'url("https://www.transparenttextures.com/patterns/cubes.png")', backgroundBlendMode: 'multiply'}}>
         <div className="text-center text-[10px] text-slate-400 my-4">今天 09:30</div>

         {messages.map((msg) => {
            const isMe = msg.sender === 'me';
            return (
               <div key={msg.id} className={`flex w-full ${isMe ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
                  <div className={`flex max-w-[80%] gap-2 ${isMe ? 'flex-row-reverse' : 'flex-row'}`}>
                     <div className="shrink-0 flex flex-col items-center">
                        <img src={msg.avatar} className="w-9 h-9 rounded-full bg-slate-200 border border-white shadow-sm object-cover" />
                     </div>

                     <div className={`flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
                        {!isMe && <span className="text-[10px] text-slate-500 mb-1 ml-1">{msg.name}</span>}

                        {msg.type === 'text' && (
                           <div className={`px-4 py-2.5 rounded-2xl text-sm shadow-sm leading-relaxed max-w-full break-words ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
                              {msg.text}
                           </div>
                        )}

                        {msg.type === 'file' && (
                           <div className={`p-3 rounded-2xl shadow-sm flex items-center space-x-3 cursor-pointer hover:opacity-90 transition max-w-full ${isMe ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-white text-slate-800 rounded-tl-none border border-slate-100'}`}>
                              <div className="p-2 bg-white/20 rounded-lg">
                                 <FileText size={24} className={isMe ? "text-white" : "text-blue-600"} />
                              </div>
                              <div className="flex flex-col overflow-hidden">
                                 <span className="font-bold text-sm truncate">{msg.text}</span>
                                 <span className={`text-[10px] ${isMe ? 'text-blue-100' : 'text-slate-400'}`}>{msg.fileSize}</span>
                              </div>
                           </div>
                        )}

                        {/* Timestamp */}
                        {/* <span className={`text-[9px] text-slate-400 mt-1 mx-1`}>{msg.timestamp}</span> */}
                     </div>
                  </div>
               </div>
            )
         })}
         <div ref={messagesEndRef} />
      </div>

      {/* Input Area */}
      <div className="bg-white border-t border-slate-200 p-3 pb-safe-area shadow-lg z-20">
         <div className="flex items-end space-x-2">
            <button onClick={() => setShowAttachMenu(!showAttachMenu)} className="p-2 text-slate-500 hover:bg-slate-100 rounded-full transition mb-1">
               {showAttachMenu ? <X size={24}/> : <Plus size={24} />}
            </button>

            <div className="flex-1 bg-slate-100 rounded-2xl flex items-center px-3 py-2 min-h-[44px]">
               <input 
                 type="text" 
                 value={inputText}
                 onChange={(e) => setInputText(e.target.value)}
                 onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                 placeholder="发送消息..." 
                 className="flex-1 bg-transparent border-none outline-none text-sm text-slate-900 placeholder:text-slate-400 max-h-24 overflow-y-auto"
               />
               <button className="p-1.5 text-slate-400 hover:text-slate-600 ml-1">
                  <Smile size={20} />
               </button>
            </div>

            {inputText.trim() ? (
               <button onClick={handleSend} className="p-3 bg-blue-600 text-white rounded-full shadow-md hover:bg-blue-700 transition active:scale-95 mb-0.5">
                  <Send size={20} className="ml-0.5" />
               </button>
            ) : (
               <button 
                 onMouseDown={() => setIsRecording(true)}
                 onMouseUp={() => setIsRecording(false)}
                 onTouchStart={() => setIsRecording(true)}
                 onTouchEnd={() => setIsRecording(false)}
                 className={`p-3 rounded-full shadow-md transition active:scale-95 mb-0.5 ${isRecording ? 'bg-rose-500 text-white animate-pulse' : 'bg-slate-100 text-slate-600'}`}
               >
                  <Mic size={20} />
               </button>
            )}
         </div>

         {/* Attach Menu */}
         {showAttachMenu && (
            <div className="grid grid-cols-4 gap-4 mt-4 pt-2 border-t border-slate-100 animate-slide-up">
               {[
                  { label: '图片', icon: Image, color: 'bg-emerald-100 text-emerald-600' },
                  { label: '拍摄', icon: Check, color: 'bg-rose-100 text-rose-600' }, // Replaced Camera with Check for now or import
                  { label: '文件', icon: FileUp, color: 'bg-blue-100 text-blue-600' },
                  { label: '经文', icon: BookOpen, color: 'bg-amber-100 text-amber-600' },
                  { label: '祷告', icon: HandHeart, color: 'bg-purple-100 text-purple-600' },
                  { label: '语音', icon: Radio, color: 'bg-indigo-100 text-indigo-600', onClick: () => onJoinRoom?.({ id: 'custom', type: 'fellowship', label: '语音通话', icon: Radio, color: 'text-blue', bg: 'bg-blue', desc: '正在通话', action: 'voice' }) },
               ].map((item, i) => (
                  <button key={i} onClick={item.onClick} className="flex flex-col items-center space-y-2 group">
                     <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${item.color} group-hover:brightness-95 transition shadow-sm`}>
                        <item.icon size={24} />
                     </div>
                     <span className="text-xs text-slate-500 font-medium">{item.label}</span>
                  </button>
               ))}
            </div>
         )}
      </div>
    </div>
  );
};

export default ChatView;
